import{NextRequest,NextResponse}from'next/server';import{z}from'zod';import{requireActiveAdmin}from'@/lib/admin-auth';import{createAdminClient}from'@/lib/supabase/admin'
const schema=z.object({bookingServiceId:z.string().uuid(),vendorId:z.string().uuid(),agreedCost:z.number().nonnegative().nullable().optional(),scheduledDate:z.string().date().nullable().optional(),requirements:z.string().trim().max(4000).nullable().optional(),internalNotes:z.string().trim().max(4000).nullable().optional()})
export async function GET(_:NextRequest,{params}:{params:Promise<{id:string}>}){const a=await requireActiveAdmin();if('response'in a)return a.response;const{id}=await params;const{data,error}=await createAdminClient().from('event_vendor_assignments').select('*,event_vendors(id,vendor_name,category,is_active),celebration_booking_services(id,service_name_snapshot)').eq('booking_id',id).order('created_at',{ascending:false});return error?NextResponse.json({error:'Unable to load vendor assignments'},{status:500}):NextResponse.json({assignments:data??[]})}
export async function POST(r:NextRequest,{params}:{params:Promise<{id:string}>}){const a=await requireActiveAdmin();if('response'in a)return a.response;const{id}=await params;let body:unknown;try{body=await r.json()}catch{return NextResponse.json({error:'Invalid JSON'},{status:400})}const p=schema.safeParse(body);if(!p.success)return NextResponse.json({error:'Please check the assignment'},{status:400});const{data,error}=await createAdminClient().rpc('create_admin_vendor_assignment',{p_booking_id:id,p_booking_service_id:p.data.bookingServiceId,p_vendor_id:p.data.vendorId,p_agreed_cost:p.data.agreedCost??null,p_scheduled_date:p.data.scheduledDate??null,p_requirements:p.data.requirements??null,p_internal_notes:p.data.internalNotes??null,p_admin_id:a.admin.id});if(error)return NextResponse.json({error:error.message},{status:error.code==='P0002'?404:error.code==='23505'||error.code==='22023'?409:500});return NextResponse.json({assignmentId:data},{status:201})}
